<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import WareState from '@/shared/components/WareState.vue'
import { qualityApi } from '../../api/quality.api'
import type { GoodFlowerVideoItem } from '../../models/quality'
import { sessionStore } from '@/store/session'

const date=ref(''),content=ref(''),item=ref<GoodFlowerVideoItem|null>(null),localVideo=ref(''),uploadedVideo=ref(''),remark=ref(''),loading=ref(true),submitting=ref(false),error=ref('')
const canSubmit=computed(()=>!!item.value&&!!localVideo.value&&!submitting.value&&sessionStore.can('quality.task.video.submit'))
async function resolveItem(){loading.value=true;error.value='';try{item.value=await qualityApi.scanGoodFlowerVideo(date.value,content.value)}catch(e){error.value=e instanceof Error?e.message:'花材识别失败'}finally{loading.value=false}}
function chooseVideo(){uni.chooseVideo({sourceType:['camera'],compressed:true,maxDuration:60,success:result=>{localVideo.value=result.tempFilePath;uploadedVideo.value=''}})}
function preview(){if(localVideo.value)uni.previewMedia({sources:[{url:localVideo.value,type:'video'}]})}
async function submit(){if(!canSubmit.value||!item.value)return;submitting.value=true;uni.showLoading({title:'正在提交',mask:true});try{if(!uploadedVideo.value)uploadedVideo.value=(await qualityApi.uploadGoodFlowerVideo(localVideo.value)).url;await qualityApi.submitGoodFlowerVideo({date:date.value,enterItemId:item.value.enterItemId,videoUrl:uploadedVideo.value,remark:remark.value});uni.showToast({title:'拍摄记录已提交',icon:'success'});setTimeout(()=>uni.navigateBack(),700)}catch(e){uni.showToast({title:e instanceof Error?e.message:'提交失败',icon:'none'})}finally{submitting.value=false;uni.hideLoading()}}
onLoad(query=>{date.value=String(query?.date||new Date().toISOString().slice(0,10));content.value=decodeURIComponent(String(query?.content||''));resolveItem()})
</script>

<template><view class="page">
  <view class="title"><strong>拍摄好花视频</strong><text>{{date}}场次</text></view>
  <WareState v-if="loading" type="loading" title="正在识别花材"/><WareState v-else-if="error" type="error" title="无法识别花材" :description="error" action-label="重新识别" @action="resolveItem"/>
  <template v-else-if="item">
    <view class="object-card"><view class="object-main"><view><strong>{{item.flowerName}} · {{item.grade}}</strong><text>{{item.location}}</text></view><span>拍摄对象</span></view><view class="supplier"><text>供应商</text><strong>{{item.supplierName}}</strong><span v-if="item.supplierTag">{{item.supplierTag}}</span></view></view>
    <view class="section"><view class="section-title"><strong>好花视频</strong><text>必填 · 仅限拍摄</text></view><view v-if="!localVideo" class="uploader" @click="chooseVideo"><text class="camera">＋</text><strong>拍摄视频</strong><small>请完整展示花材品质，最长60秒</small></view><view v-else class="video-ready"><view @click="preview"><text>▶</text></view><view><strong>视频已拍摄</strong><small>提交前可播放确认</small></view><button @click="chooseVideo">重拍</button></view></view>
    <view class="section"><view class="section-title"><strong>拍摄说明</strong><text>{{remark.length}}/200</text></view><textarea v-model="remark" maxlength="200" placeholder="选填，例如花型、成熟度或需要关注的特点"/></view>
    <view class="notice"><strong>拍摄要求</strong><text>保持画面清晰稳定，花头、枝干及整体品相应完整入镜；提交后计入本场次拍摄进度。</text></view>
  </template>
  <view v-if="item" class="footer"><button :disabled="!canSubmit" @click="submit">{{submitting?'正在提交…':'确认提交视频'}}</button></view>
</view></template>

<style scoped lang="scss">
.page{min-height:100vh;padding:24rpx 24rpx 180rpx}.title{display:flex;align-items:flex-end;justify-content:space-between;margin:6rpx 4rpx 22rpx}.title strong{font-size:31rpx}.title text{color:var(--wms-text-secondary);font-size:18rpx}.object-card,.section,.notice{margin-bottom:16rpx;padding:22rpx;border-radius:20rpx;background:#fff}.object-main{display:flex;align-items:flex-start;justify-content:space-between}.object-main strong,.object-main text{display:block}.object-main strong{font-size:27rpx}.object-main text{margin-top:8rpx;color:var(--wms-primary-700);font-size:20rpx;font-weight:700}.object-main>span{padding:6rpx 10rpx;border-radius:8rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:16rpx}.supplier{display:flex;align-items:center;gap:12rpx;margin-top:20rpx;padding-top:16rpx;border-top:1rpx solid var(--wms-border)}.supplier text{color:var(--wms-text-secondary);font-size:17rpx}.supplier strong{font-size:20rpx}.supplier span{padding:4rpx 8rpx;border-radius:6rpx;background:#fff1da;color:#9b5c00;font-size:15rpx}.section-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:16rpx}.section-title strong{font-size:22rpx}.section-title text{color:var(--wms-text-secondary);font-size:16rpx}.uploader{display:flex;align-items:center;justify-content:center;flex-direction:column;height:250rpx;border:2rpx dashed #bed4d0;border-radius:16rpx;background:var(--wms-background)}.camera{font-size:44rpx;color:var(--wms-primary-700)}.uploader strong{margin-top:3rpx;font-size:21rpx}.uploader small{margin-top:9rpx;color:var(--wms-text-secondary);font-size:16rpx}.video-ready{display:flex;align-items:center;gap:16rpx;padding:15rpx;border-radius:15rpx;background:var(--wms-background)}.video-ready>view:first-child{display:flex;align-items:center;justify-content:center;width:90rpx;height:90rpx;border-radius:12rpx;background:var(--wms-primary-900);color:#fff}.video-ready>view:nth-child(2){flex:1}.video-ready strong,.video-ready small{display:block}.video-ready small{margin-top:7rpx;color:var(--wms-text-secondary);font-size:16rpx}.video-ready button{margin:0;padding:0 18rpx;border:0;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:17rpx;line-height:55rpx}.video-ready button:after{border:0}textarea{box-sizing:border-box;width:100%;height:150rpx;padding:16rpx;border-radius:14rpx;background:var(--wms-background);font-size:19rpx}.notice{background:var(--wms-surface-soft)}.notice strong,.notice text{display:block}.notice strong{color:var(--wms-primary-700);font-size:19rpx}.notice text{margin-top:8rpx;color:var(--wms-text-secondary);font-size:17rpx;line-height:1.6}.footer{position:fixed;right:0;bottom:0;left:0;padding:18rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));background:rgba(255,255,255,.96);box-shadow:0 -8rpx 24rpx rgba(23,43,41,.06)}.footer button{height:84rpx;border:0;border-radius:16rpx;background:var(--wms-primary-700);color:#fff;font-size:23rpx;font-weight:700;line-height:84rpx}.footer button:after{border:0}.footer button[disabled]{background:#c8d5d2;color:#fff}
</style>
